import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    email_pattern = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b')
    def process_item(item):
        if isinstance(item, dict):
            return {k: process_item(v) for k, v in item.items() if v is not None}
        elif isinstance(item, list):
            return [process_item(i) for i in item if i is not None]
        elif isinstance(item, str):
            return re.sub(email_pattern, REPLACE_NONE, item)
        else:
            return item
    processed_data = process_item(data)
    def extract_values(obj):
        if isinstance(obj, dict):
            for value in obj.values():
                yield from extract_values(value)
        elif isinstance(obj, list):
            for item in obj:
                yield from extract_values(item)
        else:
            yield obj
    values = list(extract_values(processed_data))
    value_counts = Counter(values)
    return {"data": processed_data, "value_counts": value_counts}

