import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    def remove_none(obj):
        if isinstance(obj, dict):
            return {k: remove_none(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [remove_none(elem) for elem in obj if elem is not None]
        else:
            return obj

    def replace_emails(obj):
        email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
        if isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_emails(elem) for elem in obj]
        elif isinstance(obj, str):
            return re.sub(email_pattern, REPLACE_NONE, obj)
        else:
            return obj

    def collect_values(obj):
        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(collect_values(v))
        elif isinstance(obj, list):
            for elem in obj:
                values.extend(collect_values(elem))
        else:
            values.append(obj)
        return values

    data = json.loads(json_str)
    data_no_none = remove_none(data)
    data_processed = replace_emails(data_no_none)
    all_values = collect_values(data_processed)
    value_counts = Counter(all_values)
    return {"data": data_processed, "value_counts": value_counts}

